        f = URI.create(""),
        g = URI.create("context:/g/x"),
        h = URI.create("context:/h"),
        i = URI.create("context:/"),
        j = URI.create("context:/.."),
        k = URI.create("servlet:/k/x"),
        l = URI.create("servlet:/l"),
        m = URI.create("servlet:/"),
